#!/usr/bin/env bash
# SPDX-License-Identifier: MPL-2.0
#
# Regenerates the self-signed test PKI used by:
#   - core/tests/testutil.cpp and core/tests/integration/test_asio_ssl.cpp,
#     via the embedded PEM constants in ../test_certs.hpp (that file is NOT
#     generated by this script -- after running this script, copy the new
#     ca.crt / server.crt / server.key / client.crt / client.key contents
#     into ../test_certs.hpp by hand);
#   - the cross-language perf harnesses that read these files directly by
#     path: bindings/node/perf/common/perf_tls.ts and
#     bindings/python/perf/perf_metrics.py look for this exact directory
#     (core/tests/certs/gen);
#   - bindings/cpp/tests/certs/gen/, bindings/dotnet/tests/certs/ and
#     bindings/java/tests/certs/, which each keep a byte-identical copy of
#     ca.crt, server.crt and server.key for their own perf harnesses
#     (perf_tls.hpp, PerfTls.cs, PerfTransport.java). Re-sync those with the
#     sync-from-core.sh script committed alongside each copy.
#
# These are throwaway, self-signed TEST credentials for local TLS tests and
# perf harnesses only. Never reuse this material outside tests, and never
# put a real hostname or organization name in the subjects below.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

# ~20 years for the leaf certs, matching the long-lived Node TLS fixture
# (framework/languages/node/test/fixtures/tls, valid to 2036). The CA is
# given a few extra days so it always outlives the leaves it signs.
CA_DAYS="${CA_DAYS:-7305}"
LEAF_DAYS="${LEAF_DAYS:-7300}"

rm -f ca.key ca.crt ca.srl server.key server.csr server.crt client.key client.csr client.crt

# --- CA -----------------------------------------------------------------
openssl genrsa -out ca.key 2048
openssl req -new -x509 -days "$CA_DAYS" -key ca.key -out ca.crt \
    -subj "/C=US/ST=Test/L=Test/O=ZLink Test CA/CN=ZLink Test CA"

# --- Server (SAN: localhost, 127.0.0.1, ::1) -----------------------------
openssl genrsa -out server.key 2048
openssl req -new -key server.key -out server.csr \
    -subj "/C=US/ST=Test/L=Test/O=ZLink Test/CN=localhost"
openssl x509 -req -days "$LEAF_DAYS" -in server.csr -CA ca.crt -CAkey ca.key \
    -CAcreateserial -out server.crt -extensions v3_req -extfile server_ext.cnf

# --- Client ---------------------------------------------------------------
openssl genrsa -out client.key 2048
openssl req -new -key client.key -out client.csr \
    -subj "/C=US/ST=Test/L=Test/O=ZLink Test/CN=Test Client"
openssl x509 -req -days "$LEAF_DAYS" -in client.csr -CA ca.crt -CAkey ca.key \
    -CAcreateserial -out client.crt

echo "Generated CA (+${CA_DAYS}d) and leaf certs (+${LEAF_DAYS}d) under $(pwd)"
echo "Remember to: (1) sync the copies in bindings/{cpp,dotnet,java}/tests/certs*"
echo "via their sync-from-core.sh, and (2) update the embedded PEM constants in"
echo "../test_certs.hpp to match the new ca.crt / server.crt+key / client.crt+key."
